{
  "passageId": "gongsun-long-later-mohists",
  "items": [
    {
      "id": "R1",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "명실 문제의 논의가 정치·윤리적 차원에서 독립적인 철학 영역으로 확대되는 시대적 전개이므로 판별 순서 3에 해당한다."
    },
    {
      "id": "R2",
      "type": "PROCESS",
      "otherName": "",
      "reason": "미분화된 물에서 개별적인 실이 분화되는 단계적 관계이며 물이 실을 일으킨다는 인과 주장과는 구별되므로 과정에 해당한다."
    },
    {
      "id": "R3",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "실을 지시한다는 명의 기능을 실들 사이의 차이를 구별하고 확정하는 기능으로 자세히 풀므로 판별 순서 7에 해당한다."
    },
    {
      "id": "R4",
      "type": "CAUSE",
      "otherName": "",
      "reason": "같은 명으로 서로 다른 실을 구별하지 못하는 일이 실제 의사소통의 혼란을 일으킨다는 설명이므로 인과·작용에 해당한다."
    },
    {
      "id": "R5",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "같은 명으로 다른 실을 지시하여 생기는 혼란에 대해 엄격한 일대일 대응을 해결책으로 제시하므로 판별 순서 4에 해당한다."
    },
    {
      "id": "R6",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "명과 실의 일대일 대응을 수단으로 삼아 명의 사용에서 오해와 문제를 방지하려는 목적을 이루고자 한다."
    },
    {
      "id": "R7",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "같은 사상가의 설명 안에서 두 단어가 지시하는 측면을 형체와 색으로 대비하므로 견해 차이가 아닌 대상 간 대조이다."
    },
    {
      "id": "R8",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "흰 말에는 색 속성이 함께한다는 사실을 흰 말과 말이 다르다는 판단의 근거로 삼으므로 판별 순서 9에 해당한다."
    },
    {
      "id": "R9",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "말을 구하는 경우와 흰 말을 구하는 경우를 데려올 수 있는 대상이라는 동일한 기준으로 비교하여 차이를 드러낸다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "형체만을 지시하는 말과 색 속성까지 지닌 흰 말의 차이를 백마비마 주장을 뒷받침하는 논거로 제시한다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "말과 흰 말을 구할 때 허용되는 대상이 다르다는 점으로 백마비마 주장을 논증하므로 근거·도출에 해당한다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "두 명이 지시하는 실이 다르다는 판단으로부터 두 명의 용법도 구분해야 한다는 결론을 도출한다."
    },
    {
      "id": "R13",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "공손룡이 일상적인 포괄적 명칭 사용을 문제 삼고 두 명의 용법을 구분해야 한다고 주장하므로 판별 순서 1의 비판에 해당한다."
    },
    {
      "id": "R14",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "명과 실은 일대일로 대응해야 한다는 일반 원칙을 말과 흰 말의 구체적인 용법 문제에 적용하므로 판별 순서 6에 해당한다."
    },
    {
      "id": "R15",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가가 흰 말도 말이라고 주장하며 공손룡의 백마비마 주장을 명시적으로 부정하므로 비판·반박에 해당한다."
    },
    {
      "id": "R16",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가는 하나의 실에 여러 명이 대응할 수 있다고 하여 공손룡의 일대일 대응 원칙을 반박한다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "흰 말을 두 명으로 지시하는 경우는 하나의 실에 여러 명이 대응할 수 있다는 설명을 보여 주는 사례이다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "검은 말을 두 명으로 지시하는 경우는 하나의 실에 여러 명이 대응한다는 설명을 구체적으로 보여 주는 사례이다."
    },
    {
      "id": "R19",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가는 하나의 명이 여러 사물을 지시할 수 있다고 하여 하나의 명은 하나의 실만 지시해야 한다는 공손룡의 주장을 부정한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "서로 다른 두 새를 모두 학이라고 부르는 사례로 하나의 명이 여러 실을 지시한다는 설명을 구체화한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "지시 범위와 상황에 따라 명을 구분하는 이론은 명과 실의 엄격한 일대일 대응을 부정하는 후기 묵가의 입장을 뒷받침한다."
    },
    {
      "id": "R22",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "달명이 지시하는 대상의 뜻을 공손룡의 물에 해당하는 천지 만물로 밝혀 주는 것으로 견해의 수용이 아닌 지시 대상의 풀이이다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "말이라는 명은 공통 속성을 공유하는 사물들을 지시하는 유명의 구체적인 예로 제시된다."
    },
    {
      "id": "R24",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "새라는 유명을 특정한 한 마리에게 사용하는 경우는 유명을 한 개체에 대응시켜 사명을 만드는 방식의 사례이다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유명을 한 개체에만 대응시키면 사명이 된다는 정의에서 새의 유명·사명 여부는 지시 대상 수에 따라 정해진다는 판단이 도출된다."
    },
    {
      "id": "R26",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가의 복수 대응론은 공손룡의 엄격한 일대일 대응론을 단순히 대비하는 데 그치지 않고 명시적으로 반박한다."
    }
  ]
}

